def strip_macro_prefix({function, arity}) do
  case Atom.to_string(function) do
    "MACRO-" <> rest -> {String.to_atom(rest), arity - 1}
    _other -> {function, arity}
  end
end

def strictest(candidates) do
  candidates
  |> Enum.map(fn {tag, dur} ->
    case is_binary(dur) && duration_to_seconds(dur) do
      {:ok, 0} -> {tag, "0d", 0}
      {:ok, seconds} -> {tag, dur, seconds}
      _ -> {tag, "0d", 0}
    end
  end)
  |> Enum.max_by(&elem(&1, 2))
  |> then(fn {tag, dur, _} -> {tag, dur} end)
end

