  cpu_snapshots = Enum.reverse(cpu_snapshots_reversed)

  %{
    average_cpu_usage:
      Enum.map_join(cpu_snapshots, ", ", fn %{cpu_usage: _cpu_usage, average_all_cores: avg} ->
