def do_handle_event(event, %{queue: queue} = state) do
  case Qex.pop(queue) do
    {{:value, _value}, _queue} -> {[], %{state | queue: Qex.push(queue, event)}}
    {:empty, _queue} -> {[event: {:output, event}], state}
  end
end

