def assemble(track) do
  dref =
    {:dref,
     %{
       children: [url: %{children: [], fields: %{flags: 1, version: 0}}],
       fields: %{entry_count: 1, flags: 0, version: 0}
     }}

  dinf = [dinf: %{children: [dref], fields: %{}}]

  [
    trak: %{
      children:
        track_header(track) ++
          [
            mdia: %{
              children:
                media_handler_header(track) ++
                  handler(track) ++
                  [
                    minf: %{
                      children:
                        media_header(track) ++ dinf ++ SampleTableBox.assemble(track.sample_table),
                      fields: %{}
                    }
                  ],
              fields: %{}
            }
          ],
      fields: %{}
    }
  ]
end

