def validate_authentication({module, keyword} = value)
    when is_atom(module) and is_list(keyword) do
  with {:ok, _module} <- validate_module(module, "authentication") do
    {:ok, value}
  end
end
def validate_authentication(other) do
  {:error, "expected :authentication to be a {module, options} tuple, got: #{inspect(other)}"}
end

def validate_module(value, name) when is_binary(name) do
  cond do
    is_atom(value) and Code.ensure_loaded?(value) -> {:ok, value}
    is_atom(value) -> {:error, "#{name} module #{inspect(value)} is not loaded"}
    true -> {:error, "expected #{name} module to be a module, got: #{inspect(value)}"}
  end
end

